import json
import pandas as pd
from datetime import datetime


FIELD_MAP = {
    "id": "user_id",
    "userId": "user_id",
    "email_address": "email",
    "full_name": "name",
    "userName": "name",
    "registration_date": "created_date",
    "created_at": "created_date",
    "joined": "created_date",
}

OUTPUT_FIELDS = ["user_id", "name", "email", "created_date", "status"]


def normalize_date(val):
    if val is None or (isinstance(val, float) and pd.isna(val)):
        return None
    s = str(val).strip()
    for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%d-%m-%Y", "%Y/%m/%d"):
        try:
            return datetime.strptime(s, fmt).strftime("%Y-%m-%d")
        except ValueError:
            continue
    return s


def normalize_row(row: dict) -> dict:
    out = {}
    for k, v in row.items():
        canonical = FIELD_MAP.get(k, k)
        out[canonical] = v
    if "user_id" in out:
        try:
            out["user_id"] = int(out["user_id"])
        except (ValueError, TypeError):
            pass
    if "created_date" in out:
        out["created_date"] = normalize_date(out["created_date"])
    return out


def load_source_a(path: str) -> dict[int, dict]:
    with open(path) as f:
        records = json.load(f)
    result = {}
    for r in records:
        row = normalize_row(r)
        uid = row["user_id"]
        result[uid] = row
    return result


def load_source_b(path: str) -> dict[int, dict]:
    df = pd.read_csv(path)
    result = {}
    for _, row in df.iterrows():
        r = normalize_row({k: (None if pd.isna(v) else v) for k, v in row.items()})
        uid = r["user_id"]
        result[uid] = r
    return result


def load_source_c(path: str) -> dict[int, dict]:
    df = pd.read_parquet(path)
    result = {}
    for _, row in df.iterrows():
        r = normalize_row({k: (None if pd.isna(v) else v) for k, v in row.items()})
        uid = r["user_id"]
        result[uid] = r
    return result


def merge(sources: list[tuple[str, dict[int, dict]]]):
    all_ids = set()
    for _, data in sources:
        all_ids.update(data.keys())

    merged_rows = []
    conflicts = []

    for uid in sorted(all_ids):
        present = [(name, data[uid]) for name, data in sources if uid in data]

        merged = {}
        for field in OUTPUT_FIELDS:
            # Collect non-None values by source priority order
            source_values = {}
            for src_name, row in present:
                v = row.get(field)
                if v is not None and not (isinstance(v, float) and pd.isna(v)):
                    source_values[src_name] = v

            if not source_values:
                merged[field] = None
                continue

            # Pick from highest-priority source that has a value
            selected = None
            selected_src = None
            for src_name, _ in sources:
                if src_name in source_values:
                    selected = source_values[src_name]
                    selected_src = src_name
                    break

            merged[field] = selected

            # Conflict: multiple sources have the field with differing values
            if len(source_values) > 1:
                unique_vals = set(str(v) for v in source_values.values())
                if len(unique_vals) > 1:
                    conflicts.append({
                        "user_id": uid,
                        "field": field,
                        "values": {k: source_values[k] for k in source_values},
                        "selected": selected,
                    })

        merged_rows.append(merged)

    return merged_rows, conflicts


def main():
    sources = [
        ("source_a", load_source_a("/data/source_a/users.json")),
        ("source_b", load_source_b("/data/source_b/users.csv")),
        ("source_c", load_source_c("/data/source_c/users.parquet")),
    ]

    merged_rows, conflicts = merge(sources)

    df = pd.DataFrame(merged_rows, columns=OUTPUT_FIELDS)
    df["user_id"] = df["user_id"].astype(int)
    df.to_parquet("/app/merged_users.parquet", index=False)
    print(f"Written {len(df)} rows to /app/merged_users.parquet")

    conflict_report = {
        "total_conflicts": len(conflicts),
        "conflicts": conflicts,
    }
    with open("/app/conflicts.json", "w") as f:
        json.dump(conflict_report, f, indent=2)
    print(f"Written {len(conflicts)} conflicts to /app/conflicts.json")


if __name__ == "__main__":
    main()

